{"cmd":"cat > /root/run_analysis.js <<'NODE'
const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const data = JSON.parse(fs.readFileSync('network.json', 'utf8'));
const baseMVA = data.baseMVA;

const busIds = data.bus.map(b => b[0]);
const busIndex = new Map(busIds.map((id, idx) => [id, idx]));

const slackBusId = (() => {
  for (const b of data.bus) {
    if (b[1] === 3) return b[0];
  }
  return busIds[0];
})();

function formatNumber(x) {
  if (Math.abs(x) < 1e-9) return '0';
  // Use 12 significant digits to keep accuracy without bloating.
  return Number(x).toPrecision(12);
}

function buildLP(caseName, rateAdjuster) {
  const nb = busIds.length;

  // Initialize bus equations with RHS = Pd
  const busEq = Array.from({ length: nb }, (_, i) => ({
    rhs: data.bus[i][2], // PD
    coeffs: new Map()
  }));

  const addCoeff = (map, varName, coef) => {
    if (coef === 0) return;
    const prev = map.get(varName) || 0;
    const next = prev + coef;
    if (Math.abs(next) < 1e-12) map.delete(varName);
    else map.set(varName, next);
  };

  // Branch contributions
  const branches = [];
  for (let i = 0; i < data.branch.length; i++) {
    const br = data.branch[i];
    const status = br[10];
    if (status === 0) continue;

    const f = br[0];
    const t = br[1];
    const x = br[3];
    let tap = br[8];
    if (!tap || tap === 0) tap = 1;
    const shiftDeg = br[9] || 0;
    const shiftRad = shiftDeg * Math.PI / 180;
    const coeff = baseMVA / (x * tap);

    let rateA = br[5];
    if (rateAdjuster) {
      rateA = rateAdjuster({ f, t, rateA });
    }

    branches.push({
      idx: i,
      f,
      t,
      coeff,
      shiftRad,
      rateA
    });

    const fIdx = busIndex.get(f);
    const tIdx = busIndex.get(t);
    if (fIdx == null || tIdx == null) continue;

    // Bus f equation updates
    addCoeff(busEq[fIdx].coeffs, `th_b${f}`, -coeff);
    addCoeff(busEq[fIdx].coeffs, `th_b${t}`, +coeff);
    busEq[fIdx].rhs += -coeff * shiftRad;

    // Bus t equation updates
    addCoeff(busEq[tIdx].coeffs, `th_b${f}`, +coeff);
    addCoeff(busEq[tIdx].coeffs, `th_b${t}`, -coeff);
    busEq[tIdx].rhs += +coeff * shiftRad;
  }

  // Generator variables and bus contributions
  const genVars = [];
  for (let i = 0; i < data.gen.length; i++) {
    const g = data.gen[i];
    const status = g[7];
    const busId = g[0];
    const pmax = g[8];
    const pmin = g[9];
    const rmax = data.reserve_capacity[i] ?? 0;

    if (status === 0) continue;

    const pg = `pg_g${i}`;
    const rg = `rg_g${i}`;
    genVars.push({ idx: i, busId, pg, rg, pmin, pmax, rmax });

    const bIdx = busIndex.get(busId);
    if (bIdx != null) {
      addCoeff(busEq[bIdx].coeffs, pg, 1);
    }
  }

  // Objective
  const objTerms = [];
  for (const gv of genVars) {
    const gc = data.gencost[gv.idx];
    const b = gc[5]; // linear coefficient
    if (Math.abs(b) > 0) {
      objTerms.push(`${formatNumber(b)} ${gv.pg}`);
    }
  }

  const lines = [];
  lines.push('Minimize');
  lines.push(` obj: ${objTerms.length ? objTerms.join(' + ') : '0'}`);
  lines.push('Subject To');

  // Bus balance constraints
  for (let i = 0; i < nb; i++) {
    const busId = busIds[i];
    const coeffs = busEq[i].coeffs;
    const rhs = busEq[i].rhs;
    const terms = [];
    for (const [v, c] of coeffs.entries()) {
      if (Math.abs(c) < 1e-12) continue;
      const sign = c >= 0 ? '+' : '-';
      const abs = Math.abs(c);
      const coefStr = Math.abs(abs - 1) < 1e-12 ? '' : `${formatNumber(abs)} `;
      if (terms.length === 0) {
        terms.push(`${c < 0 ? '-' : ''}${coefStr}${v}`.trim());
      } else {
        terms.push(`${sign} ${coefStr}${v}`.trim());
      }
    }
    const expr = terms.length ? terms.join(' ') : '0';
    lines.push(` bal_b${busId}: ${expr} = ${formatNumber(rhs)}`);
  }

  // Slack bus angle
  lines.push(` slack_b${slackBusId}: th_b${slackBusId} = 0`);

  // Line flow constraints
  let lineCount = 0;
  for (const br of branches) {
    const limit = br.rateA;
    if (!limit || limit <= 0) continue;
    const coeff = br.coeff;
    const shift = br.shiftRad;
    const fVar = `th_b${br.f}`;
    const tVar = `th_b${br.t}`;
    const rhsUp = limit + coeff * shift;
    const rhsDn = -limit + coeff * shift;
    lines.push(` line_up_${lineCount}: ${formatNumber(coeff)} ${fVar} - ${formatNumber(coeff)} ${tVar} <= ${formatNumber(rhsUp)}`);
    lines.push(` line_dn_${lineCount}: ${formatNumber(coeff)} ${fVar} - ${formatNumber(coeff)} ${tVar} >= ${formatNumber(rhsDn)}`);
    lineCount++;
  }

  // Reserve requirement
  if (genVars.length) {
    const rgTerms = genVars.map(gv => gv.rg).join(' + ');
    lines.push(` reserve_req: ${rgTerms} >= ${formatNumber(data.reserve_requirement)}`);
  } else {
    lines.push(` reserve_req: 0 >= ${formatNumber(data.reserve_requirement)}`);
  }

  // Capacity coupling constraints
  for (const gv of genVars) {
    lines.push(` cap_g${gv.idx}: ${gv.pg} + ${gv.rg} <= ${formatNumber(gv.pmax)}`);
  }

  lines.push('Bounds');

  // Generator bounds
  for (const gv of genVars) {
    lines.push(` ${formatNumber(gv.pmin)} <= ${gv.pg} <= ${formatNumber(gv.pmax)}`);
    lines.push(` 0 <= ${gv.rg} <= ${formatNumber(gv.rmax)}`);
  }

  // Theta bounds (free)
  for (const busId of busIds) {
    lines.push(` th_b${busId} free`);
  }

  lines.push('End');

  return { lp: lines.join('\n'), branches, genVars };
}

function parseSolution(solText) {
  const lines = solText.split(/\r?\n/);
  const rowMarginal = new Map();
  const colValue = new Map();
  let inRows = false;
  let inCols = false;
  let objective = null;

  for (const line of lines) {
    if (line.startsWith('Objective:')) {
      const m = line.match(/Objective:\s+\w+\s+=\s+([+-]?[0-9.eE+-]+)/);
      if (m) objective = Number(m[1]);
    }

    if (line.includes('Row name') && line.includes('Marginal')) {
      inRows = true;
      inCols = false;
      continue;
    }
    if (line.includes('Column name') && line.includes('Marginal')) {
      inCols = true;
      inRows = false;
      continue;
    }

    if (inRows) {
      if (!line.trim() || line.startsWith('----')) continue;
      const parts = line.trim().split(/\s+/);
      if (!/^[0-9]+$/.test(parts[0])) continue;
      const name = parts[1];
      const marginal = Number(parts[parts.length - 1]);
      rowMarginal.set(name, marginal);
    }

    if (inCols) {
      if (!line.trim() || line.startsWith('----')) continue;
      const parts = line.trim().split(/\s+/);
      if (!/^[0-9]+$/.test(parts[0])) continue;
      const name = parts[1];
      const activity = Number(parts[3]);
      colValue.set(name, activity);
    }
  }

  return { rowMarginal, colValue, objective };
}

function solveCase(caseName, rateAdjuster) {
  const { lp, branches, genVars } = buildLP(caseName, rateAdjuster);
  const tmpLp = path.join('/tmp', `opf_${caseName}.lp`);
  const tmpSol = path.join('/tmp', `opf_${caseName}.sol`);
  fs.writeFileSync(tmpLp, lp);

  execSync(`glpsol --lp ${tmpLp} -o ${tmpSol}`, { stdio: 'ignore' });
  const solText = fs.readFileSync(tmpSol, 'utf8');
  const { rowMarginal, colValue } = parseSolution(solText);

  // LMPs
  const lmpByBus = busIds.map(busId => ({
    bus: busId,
    lmp_dollars_per_MWh: rowMarginal.get(`bal_b${busId}`) ?? 0
  }));

  const reserveMcp = rowMarginal.get('reserve_req') ?? 0;

  // Generator dispatch values
  const pgByGen = new Map();
  for (const gv of genVars) {
    pgByGen.set(gv.idx, colValue.get(gv.pg) ?? 0);
  }

  // Total cost (include constant term)
  let totalCost = 0;
  for (let i = 0; i < data.gen.length; i++) {
    const gc = data.gencost[i];
    const a = gc[4];
    const b = gc[5];
    const c = gc[6];
    const pg = pgByGen.get(i) ?? 0;
    totalCost += a * pg * pg + b * pg + c;
  }

  // Binding lines
  const bindingLines = [];
  const thetaByBus = new Map();
  for (const busId of busIds) {
    thetaByBus.set(busId, colValue.get(`th_b${busId}`) ?? 0);
  }

  for (const br of branches) {
    if (!br.rateA || br.rateA <= 0) continue;
    const thF = thetaByBus.get(br.f) ?? 0;
    const thT = thetaByBus.get(br.t) ?? 0;
    const flow = br.coeff * (thF - thT - br.shiftRad);
    const limit = br.rateA;
    if (Math.abs(flow) >= 0.99 * limit) {
      bindingLines.push({
        from: br.f,
        to: br.t,
        flow_MW: flow,
        limit_MW: limit
      });
    }
  }

  return { totalCost, lmpByBus, reserveMcp, bindingLines, branches, thetaByBus };
}

// Identify adjusted lines for counterfactual
const adjustedLines = new Set();
for (const br of data.branch) {
  const f = br[0];
  const t = br[1];
  if ((f === 64 && t === 1501) || (f === 1501 && t === 64)) {
    adjustedLines.add(`${f}-${t}`);
  }
}

const base = solveCase('base', null);
const counterfactual = solveCase('counterfactual', ({ f, t, rateA }) => {
  if ((f === 64 && t === 1501) || (f === 1501 && t === 64)) {
    return rateA * 1.2;
  }
  return rateA;
});

// Impact analysis
const lmpMapBase = new Map(base.lmpByBus.map(b => [b.bus, b.lmp_dollars_per_MWh]));
const lmpMapCf = new Map(counterfactual.lmpByBus.map(b => [b.bus, b.lmp_dollars_per_MWh]));
const lmpDrops = busIds.map(busId => {
  const baseLmp = lmpMapBase.get(busId) ?? 0;
  const cfLmp = lmpMapCf.get(busId) ?? 0;
  return { bus: busId, base_lmp: baseLmp, cf_lmp: cfLmp, delta: cfLmp - baseLmp };
});

lmpDrops.sort((a, b) => a.delta - b.delta);
const topDrops = lmpDrops.slice(0, 3);

// Check congestion relieved for adjusted line(s)
let adjustedBinding = false;
for (const br of counterfactual.branches) {
  const isAdjusted = (br.f === 64 && br.t === 1501) || (br.f === 1501 && br.t === 64);
  if (!isAdjusted || !br.rateA || br.rateA <= 0) continue;
  const thF = counterfactual.thetaByBus.get(br.f) ?? 0;
  const thT = counterfactual.thetaByBus.get(br.t) ?? 0;
  const flow = br.coeff * (thF - thT - br.shiftRad);
  if (Math.abs(flow) >= 0.99 * br.rateA) {
    adjustedBinding = true;
    break;
  }
}

const report = {
  base_case: {
    total_cost_dollars_per_hour: base.totalCost,
    lmp_by_bus: base.lmpByBus,
    reserve_mcp_dollars_per_MWh: base.reserveMcp,
    binding_lines: base.bindingLines
  },
  counterfactual: {
    total_cost_dollars_per_hour: counterfactual.totalCost,
    lmp_by_bus: counterfactual.lmpByBus,
    reserve_mcp_dollars_per_MWh: counterfactual.reserveMcp,
    binding_lines: counterfactual.bindingLines
  },
  impact_analysis: {
    cost_reduction_dollars_per_hour: base.totalCost - counterfactual.totalCost,
    buses_with_largest_lmp_drop: topDrops,
    congestion_relieved: !adjustedBinding
  }
};

fs.writeFileSync('report.json', JSON.stringify(report, null, 2));
console.log('report.json written');
NODE
"}

